export default function EmployeeAvatar({
  name,
  large = false,
}: {
  name: string;
  large?: boolean;
}) {
  const initials = name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
  return (
    <span className={`avatar${large ? " avatar-large" : ""}`} aria-hidden="true">
      {initials || "?"}
    </span>
  );
}
