"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import EmployeeAvatar from "@/components/employee-avatar";
import EmployeeForm from "@/components/employee-form";
import type { Employee } from "@/model/model";
import { employeeAPI } from "@/externals/api-service";

const salaryFormatter = new Intl.NumberFormat("en", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

export default function EmployeeRecord({
  id,
  edit = false,
  message,
}: {
  id: string;
  edit?: boolean;
  message?: string;
}) {
  const [employee, setEmployee] = useState<Employee | null>(null);
  const [error, setError] = useState("");
  const [revision, setRevision] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    employeeAPI
      .get(id, controller.signal)
      .then((response) => {
        if (!controller.signal.aborted) {
          setEmployee(response.data);
          setError("");
        }
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setError(
            error instanceof Error
              ? error.message
              : "Could not load the employee.",
          );
        }
      });
    return () => controller.abort();
  }, [id, revision]);

  return (
    <div className="narrow-page">
      <Link href="/" className="back-link">
        ← All employees
      </Link>
      <div className="page-heading">
        <div>
          <p className="eyebrow">EMPLOYEE DIRECTORY</p>
          <h1>{edit ? "Edit employee" : "View employee"}</h1>
          <p className="muted">
            {edit
              ? "Update the employee details below."
              : "Employee information at a glance."}
          </p>
        </div>
      </div>
      {!edit && message && (
        <p className="notice notice-success" role="status">
          {message}
        </p>
      )}
      {error ? (
        <div className="notice notice-error" role="alert">
          <span>{error}</span>
          <button
            className="text-button"
            onClick={() => {
              setError("");
              setEmployee(null);
              setRevision((value) => value + 1);
            }}
          >
            Try again
          </button>
        </div>
      ) : !employee ? (
        <div className="card empty-state" role="status">
          Loading employee...
        </div>
      ) : edit ? (
        <EmployeeForm key={JSON.stringify(employee)} employee={employee} />
      ) : (
        <section className="card profile-card" aria-label="Employee details">
          <div className="profile-heading">
            <div className="employee-cell">
              <EmployeeAvatar name={employee.name} large />
              <div>
                <h2>{employee.name}</h2>
                <p className="muted">{employee.department}</p>
              </div>
            </div>
            <Link
              className="button button-primary"
              href={`/employees/${encodeURIComponent(String(employee.id))}/edit`}
            >
              Edit employee
            </Link>
          </div>
          <dl className="detail-grid">
            <div>
              <dt>Employee ID</dt>
              <dd>{employee.id}</dd>
            </div>
            <div>
              <dt>Full name</dt>
              <dd>{employee.name}</dd>
            </div>
            <div>
              <dt>Department</dt>
              <dd>{employee.department}</dd>
            </div>
            <div>
              <dt>Salary</dt>
              <dd>
                {salaryFormatter.format(employee.salary)}
              </dd>
            </div>
          </dl>
        </section>
      )}
    </div>
  );
}
