import type { Employee, EmployeeInput, GenericResponse } from "@/model/model";

const baseUrl = (
  process.env.NEXT_PUBLIC_API_BASE_URL?.trim() || "https://localhost:7047"
).replace(/\/+$/, "");

const invalidApiData = "The API returned an invalid employee response.";

export class ApiError extends Error {
  constructor(message: string, public readonly status: number) {
    super(message);
    this.name = "ApiError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isEmployeeId(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isInteger(value) &&
    value > 0 &&
    value <= 2_147_483_647
  );
}

function parseId(id: string | number): number {
  if (typeof id === "string" && !/^\d+$/.test(id)) {
    throw new ApiError("Invalid employee ID.", 400);
  }

  const value = Number(id);
  if (!isEmployeeId(value)) throw new ApiError("Invalid employee ID.", 400);
  return value;
}

function parseEmployee(value: unknown): Employee {
  if (
    !isRecord(value) ||
    !isEmployeeId(value.id) ||
    typeof value.name !== "string" ||
    typeof value.department !== "string" ||
    typeof value.salary !== "number" ||
    !Number.isFinite(value.salary)
  ) {
    throw new ApiError(invalidApiData, 502);
  }

  return {
    id: value.id,
    name: value.name,
    department: value.department,
    salary: value.salary,
  };
}

function parseEmployees(value: unknown): Employee[] {
  if (!Array.isArray(value)) throw new ApiError(invalidApiData, 502);

  const ids = new Set<number>();
  return value.map((item) => {
    const employee = parseEmployee(item);
    if (ids.has(employee.id)) throw new ApiError(invalidApiData, 502);
    ids.add(employee.id);
    return employee;
  });
}

async function request<T>(
  path: string,
  method: "GET" | "POST" | "PUT" | "DELETE",
  parseData: (data: unknown) => T,
  body?: Employee,
  signal?: AbortSignal,
): Promise<GenericResponse<T>> {
  let response: Response;

  try {
    response = await fetch(`${baseUrl}${path}`, {
      method,
      signal,
      cache: "no-store",
      headers: {
        Accept: "application/json",
        ...(body ? { "Content-Type": "application/json" } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch (error) {
    if (signal?.aborted) throw error;
    throw new ApiError(
      "Could not reach the employee API. Check that the backend is running, its HTTPS certificate is trusted, and CORS allows this app.",
      0,
    );
  }

  const payload: unknown = await response.json().catch(() => null);

  signal?.throwIfAborted();

  if (!response.ok) {
    throw new ApiError(
      isRecord(payload) && typeof payload.message === "string" && payload.message.trim()
        ? payload.message.trim()
        : `The API request failed (${response.status}). Please try again.`,
      response.status,
    );
  }

  if (
    !isRecord(payload) ||
    typeof payload.isSuccess !== "boolean" ||
    typeof payload.message !== "string" ||
    typeof payload.status !== "number" ||
    !Number.isInteger(payload.status)
  ) {
    throw new ApiError(invalidApiData, 502);
  }

  if (!payload.isSuccess || payload.status < 200 || payload.status >= 300) {
    throw new ApiError(payload.message.trim() || "The employee operation failed.", payload.status);
  }

  return {
    data: parseData(payload.data),
    isSuccess: payload.isSuccess,
    message: payload.message,
    status: payload.status,
  };
}

export const employeeAPI = {
  list(signal?: AbortSignal): Promise<GenericResponse<Employee[]>> {
    return request("/List", "GET", parseEmployees, undefined, signal);
  },

  async get(id: string | number, signal?: AbortSignal): Promise<GenericResponse<Employee>> {
    return request(`/GetById/${parseId(id)}`, "GET", parseEmployee, undefined, signal);
  },

  create(data: EmployeeInput): Promise<GenericResponse<number>> {
    return request("/Add", "POST", (value) => {
      if (!isEmployeeId(value)) throw new ApiError(invalidApiData, 502);
      return value;
    }, { ...data, id: 0 });
  },

  async update(id: string | number, data: EmployeeInput): Promise<GenericResponse<Employee>> {
    return request("/Update", "PUT", parseEmployee, { ...data, id: parseId(id) });
  },

  async delete(id: string | number): Promise<GenericResponse<boolean>> {
    return request(`/Delete/${parseId(id)}`, "DELETE", (value) => {
      if (typeof value !== "boolean") throw new ApiError(invalidApiData, 502);
      if (!value) throw new ApiError("The API did not delete the employee.", 409);
      return value;
    });
  },
};
